  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 0.0, ease(EASE_IN_OUT_SINE, 0.0));
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 0.5, ease(EASE_IN_OUT_SINE, 0.5));
