static int flicker_main(int index, int frames, double step) {
  Canvas cv;
  if (canvas_init(&cv, 466, 466, malloc) != 0) return 1;
  HackRunner *r = runner_create(&cv);
  scratch_step = step;
  xshim_set_clock(scratch_clock);
  if (!r || runner_start(r, index) != 0) return 1;
  for (int i = 0; i < frames; i++) {
    runner_step(r);
    long lit = 0, green = 0;
    for (long k = 0; k < (long)cv.w * cv.h; k++) {
      lit += cv.px[k] != 0;
      green += (px_swap(cv.px[k]) >> 5) & 63;
    }
    printf("%d %ld %ld\n", i, lit, green);
  }
  runner_destroy(r);
  canvas_free(&cv);
  return 0;
}

