#include <esp_timer.h>
static const int kPinTE = 38;
static const int kTeRing = 512;
static volatile uint32_t teAt[kTeRing];
static volatile uint8_t teLevel[kTeRing];
static volatile uint32_t teHead;
static void IRAM_ATTR teIsr() {
  uint32_t i = teHead;
  teAt[i % kTeRing] = (uint32_t)esp_timer_get_time();
  teLevel[i % kTeRing] = (uint8_t)gpio_get_level((gpio_num_t)kPinTE);
  teHead = i + 1;
}
static const int kPushLog = 64;
static uint32_t pushStart[kPushLog], pushEnd[kPushLog];
static int pushCount;
static uint32_t teReportedHead;

static void teInit() {
  pinMode(kPinTE, INPUT);
  attachInterrupt(kPinTE, teIsr, CHANGE);
}

static void teReport() {
  uint32_t head = teHead;
  uint32_t n = head - teReportedHead;
  if (n > (uint32_t)kTeRing) n = kTeRing;
  static uint32_t rise[kTeRing];
  int nr = 0;
  uint32_t highSum = 0, lastRise = 0;
  int nh = 0;
  bool haveRise = false;
  for (uint32_t k = head - n; k != head; k++) {
    uint32_t t = teAt[k % kTeRing];
    if (teLevel[k % kTeRing]) {
      rise[nr++] = t;
      lastRise = t;
      haveRise = true;
    } else if (haveRise) {
      highSum += t - lastRise;
      nh++;
      haveRise = false;
    }
  }
  uint32_t pSum = 0, pMin = 0xFFFFFFFF, pMax = 0;
  for (int i = 1; i < nr; i++) {
    uint32_t d = rise[i] - rise[i - 1];
    pSum += d;
    if (d < pMin) pMin = d;
    if (d > pMax) pMax = d;
  }
  uint32_t sSum = 0, sMin = 0xFFFFFFFF, sMax = 0, dSum = 0;
  int ns = 0, inPush = 0;
  for (int p = 0; p < pushCount; p++) {
    uint32_t after = 0;
    bool found = false;
    for (int i = 0; i < nr; i++)
      if ((int32_t)(rise[i] - pushStart[p]) <= 0) {
        after = pushStart[p] - rise[i];
        found = true;
