    for (int i = 0; i < nr; i++)
      if ((int32_t)(rise[i] - pushStart[p]) > 0 &&
          (int32_t)(rise[i] - pushEnd[p]) <= 0)
        inPush++;
    dSum += pushEnd[p] - pushStart[p];
    if (found) {
      sSum += after;
      if (after < sMin) sMin = after;
      if (after > sMax) sMax = after;
      ns++;
    }
