#include <stdint.h>
#include <unity.h>

#include "runner/te_sync.h"

#define PERIOD 16819u /* the panel's measured TE period, in microseconds */

static TeSync s;

void setUp(void) { te_sync_init(&s, 1100, 100000); }
void tearDown(void) {}

/* Two rising edges one period apart teach it the period. */
static void learn_from(uint32_t first_rise) {
  te_sync_edge(&s, first_rise, 1);
  te_sync_edge(&s, first_rise + 1100, 0);
  te_sync_edge(&s, first_rise + PERIOD, 1);
}

void test_without_any_edge_it_never_waits(void) {
  TEST_ASSERT_EQUAL_UINT32(0, te_sync_wait_us(&s, 5000));
}

void test_one_edge_is_not_enough_to_know_the_period(void) {
  te_sync_edge(&s, 1000, 1);
  TEST_ASSERT_EQUAL_UINT32(0, te_sync_wait_us(&s, 1200));
}

void test_the_period_is_the_gap_between_rising_edges(void) {
  learn_from(10000);
  TEST_ASSERT_EQUAL_UINT32(PERIOD, te_sync_period_us(&s));
}

void test_falling_edges_do_not_count_as_periods(void) {
  te_sync_edge(&s, 10000, 1);
  te_sync_edge(&s, 11100, 0);
  TEST_ASSERT_EQUAL_UINT32(0, te_sync_period_us(&s));
}

void test_it_waits_for_the_offset_after_the_latest_rising_edge(void) {
  learn_from(10000);
  const uint32_t rise = 10000 + PERIOD;
  TEST_ASSERT_EQUAL_UINT32(1100, te_sync_wait_us(&s, rise));
  TEST_ASSERT_EQUAL_UINT32(600, te_sync_wait_us(&s, rise + 500));
  TEST_ASSERT_EQUAL_UINT32(0, te_sync_wait_us(&s, rise + 1100));
}

void test_past_the_offset_it_waits_for_the_next_period(void) {
  learn_from(10000);
  const uint32_t rise = 10000 + PERIOD;
  TEST_ASSERT_EQUAL_UINT32(PERIOD - 2000 + 1100, te_sync_wait_us(&s, rise + 2000));
  TEST_ASSERT_EQUAL_UINT32(1100 - 1, te_sync_wait_us(&s, rise + PERIOD + 1));
}

void test_the_wait_never_exceeds_one_period(void) {
  learn_from(10000);
  const uint32_t rise = 10000 + PERIOD;
  for (uint32_t t = 0; t < 3 * PERIOD; t += 137)
    TEST_ASSERT_TRUE(te_sync_wait_us(&s, rise + t) < PERIOD);
}

void test_a_later_offset_waits_longer(void) {
  te_sync_init(&s, 5000, 100000);
  learn_from(10000);
  TEST_ASSERT_EQUAL_UINT32(5000, te_sync_wait_us(&s, 10000 + PERIOD));
}

void test_an_offset_longer_than_the_period_wraps_into_it(void) {
  te_sync_init(&s, PERIOD + 300, 100000);
  learn_from(10000);
  TEST_ASSERT_EQUAL_UINT32(300, te_sync_wait_us(&s, 10000 + PERIOD));
}

void test_the_microsecond_counter_wrapping_does_not_confuse_it(void) {
  const uint32_t first = 0xFFFFFFFFu - 5000u;
  learn_from(first); /* the second rise lands after the counter wrapped */
  const uint32_t rise = first + PERIOD;
  TEST_ASSERT_TRUE(rise < first);
  TEST_ASSERT_EQUAL_UINT32(PERIOD, te_sync_period_us(&s));
  TEST_ASSERT_EQUAL_UINT32(600, te_sync_wait_us(&s, rise + 500));
}

void test_when_the_edges_stop_it_stops_waiting(void) {
  learn_from(10000);
  const uint32_t rise = 10000 + PERIOD;
  TEST_ASSERT_TRUE(te_sync_wait_us(&s, rise + 90000) > 0 ||
                   te_sync_wait_us(&s, rise + 90000) == 0);
  TEST_ASSERT_EQUAL_UINT32(0, te_sync_wait_us(&s, rise + 100001));
  TEST_ASSERT_EQUAL_UINT32(0, te_sync_wait_us(&s, rise + 5000000));
}

void test_a_glitch_edge_is_not_taken_for_a_period(void) {
  learn_from(10000);
  const uint32_t rise = 10000 + PERIOD;
  te_sync_edge(&s, rise + 300, 1); /* far too soon after the last rise */
  TEST_ASSERT_EQUAL_UINT32(PERIOD, te_sync_period_us(&s));
  TEST_ASSERT_EQUAL_UINT32(1100, te_sync_wait_us(&s, rise));
}

void test_a_missed_edge_does_not_double_the_period(void) {
  learn_from(10000);
  const uint32_t rise = 10000 + PERIOD;
  te_sync_edge(&s, rise + 2 * PERIOD, 1); /* one pulse never reached us */
  TEST_ASSERT_EQUAL_UINT32(PERIOD, te_sync_period_us(&s));
}

void test_the_period_follows_a_slow_drift(void) {
  uint32_t t = 10000;
  te_sync_edge(&s, t, 1);
  for (int i = 0; i < 400; i++) {
    t += PERIOD + 40; /* the panel settles 40 us slower */
    te_sync_edge(&s, t, 1);
  }
  const uint32_t p = te_sync_period_us(&s);
  TEST_ASSERT_TRUE(p >= PERIOD + 30 && p <= PERIOD + 50);
}

int main(void) {
  UNITY_BEGIN();
  RUN_TEST(test_without_any_edge_it_never_waits);
  RUN_TEST(test_one_edge_is_not_enough_to_know_the_period);
  RUN_TEST(test_the_period_is_the_gap_between_rising_edges);
  RUN_TEST(test_falling_edges_do_not_count_as_periods);
  RUN_TEST(test_it_waits_for_the_offset_after_the_latest_rising_edge);
  RUN_TEST(test_past_the_offset_it_waits_for_the_next_period);
  RUN_TEST(test_the_wait_never_exceeds_one_period);
  RUN_TEST(test_a_later_offset_waits_longer);
  RUN_TEST(test_an_offset_longer_than_the_period_wraps_into_it);
  RUN_TEST(test_the_microsecond_counter_wrapping_does_not_confuse_it);
  RUN_TEST(test_when_the_edges_stop_it_stops_waiting);
  RUN_TEST(test_a_glitch_edge_is_not_taken_for_a_period);
  RUN_TEST(test_a_missed_edge_does_not_double_the_period);
  RUN_TEST(test_the_period_follows_a_slow_drift);
  return UNITY_END();
}

#ifndef RUNNER_TE_SYNC_H
#define RUNNER_TE_SYNC_H

#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Times a push to the panel's refresh. The AMOLED scans its memory top to
 * bottom 60 times a second, and a full push takes about two refreshes, so a
 * push that starts at a random moment shows two pictures at once, with a seam
 * between them: a thin line that moved a few pixels can fall in the gap and
 * vanish for a frame. The panel's TE line pulses once a refresh. Starting a
 * push at the same point in every cycle puts the seam where it is chosen, and
 * the right point keeps the write ahead of the scan so there is none.
 *
 * An interrupt feeds it the edges of TE with the microsecond they arrived; the
 * main loop asks how long to wait. Times are 32-bit microseconds that may
 * wrap. */
typedef struct {
  volatile uint32_t last_rise_us;
  volatile uint32_t period_us; /* 0 until two rising edges one period apart */
  volatile uint32_t rises;     /* rising edges accepted, saturating at 2 */
  uint32_t offset_us;
  uint32_t timeout_us;
} TeSync;

/* A rising edge this soon after the last, or later than the longest period
 * that can be a missed edge, is not a refresh. */
#define TE_SYNC_MIN_PERIOD_US 8000u
#define TE_SYNC_MAX_PERIOD_US 33000u

/* offset_us is how long after a rising edge a push should start. When no edge
 * has arrived for timeout_us the panel is taken to have stopped pulsing and
 * waiting is switched off, so a dead line cannot hang the display. */
void te_sync_init(TeSync *s, uint32_t offset_us, uint32_t timeout_us);

/* One edge of the TE line (level 1 is a rising edge) at now_us. Safe to call
 * from an interrupt. */
void te_sync_edge(TeSync *s, uint32_t now_us, int level);

/* The refresh period learnt so far, or 0. */
uint32_t te_sync_period_us(const TeSync *s);

/* Microseconds from now_us until a push should start: less than one period,
 * and 0 when the period is unknown or the edges have stopped. */
uint32_t te_sync_wait_us(const TeSync *s, uint32_t now_us);

#ifdef __cplusplus
}
#endif

#endif

#include "runner/te_sync.h"

void te_sync_init(TeSync *s, uint32_t offset_us, uint32_t timeout_us) {
  s->last_rise_us = 0;
  s->period_us = 0;
  s->rises = 0;
  s->offset_us = offset_us;
  s->timeout_us = timeout_us;
}

void te_sync_edge(TeSync *s, uint32_t now_us, int level) {
  if (!level) return;
  if (s->rises == 0) {
    s->last_rise_us = now_us;
    s->rises = 1;
    return;
  }
  const uint32_t gap = now_us - s->last_rise_us;
  if (gap < TE_SYNC_MIN_PERIOD_US) return; /* a glitch: keep the true edge */

  const uint32_t period = s->period_us;
  if (gap <= TE_SYNC_MAX_PERIOD_US) {
    s->period_us = period ? period + (gap - period) / 8 : gap;
    if (!period || (int32_t)(gap - period) < 0)
      s->period_us = period ? period - (period - gap) / 8 : gap;
    s->rises = 2;
  } else if (period) {
    /* Edges the interrupt missed leave a whole number of periods; anything
     * else is a restart, and the period is learnt again. */
    const uint32_t k = (gap + period / 2) / period;
    const uint32_t off = gap > k * period ? gap - k * period : k * period - gap;
    if (k < 2 || off > period / 16) {
      s->period_us = 0;
      s->rises = 1;
    }
  } else {
    s->rises = 1;
  }
  s->last_rise_us = now_us;
}

uint32_t te_sync_period_us(const TeSync *s) { return s->period_us; }

uint32_t te_sync_wait_us(const TeSync *s, uint32_t now_us) {
  const uint32_t period = s->period_us;
  if (!period) return 0;
  uint32_t since = now_us - s->last_rise_us;
  if ((int32_t)since < 0) since = 0; /* the edge landed just after now was read */
  if (since > s->timeout_us) return 0;
  const uint32_t into = since % period;
  const uint32_t offset = s->offset_us % period;
  return into <= offset ? offset - into : period - into + offset;
}

