static void fill_everything_with(float r, float g, float b, float z) {
  glColor3f(r, g, b);
  glBegin(GL_TRIANGLES);
  glVertex3f(-1, -1, z);
  glVertex3f(3, -1, z);
  glVertex3f(-1, 3, z);
